private void pushback(final byte[] buf, final int offset, final int length) throws IOException {
    // Validate offset and length
    if (offset < 0 || length < 0 || (offset + length) > buf.length) {
        throw new IOException("Invalid offset or length; ensure offset >= 0, length >= 0, and offset + length <= buf.length.");
    }

    // Create a local variable for PushbackInputStream
    PushbackInputStream pushbackStream;
    if (inputStream instanceof PushbackInputStream) {
        pushbackStream = (PushbackInputStream) inputStream;
    } else {
        pushbackStream = new PushbackInputStream(inputStream, buf.length);
    }

    try {
        // Use the local PushbackInputStream variable to unread the bytes
        pushbackStream.unread(buf, offset, length);
        pushedBackBytes(length);
    } catch (IndexOutOfBoundsException e) {
        throw new IOException("Error during pushback operation: " + e.getMessage(), e);
    }
}

